#include <stdio.h>

int main() {
    int fetch = 4, indirect = 3, execute = 5, interrupt = 2;
    int with_indirect = fetch + indirect + execute;  /* 需间址：取指+间址+执行 */
    int normal = fetch + execute;                    /* 普通：取指+执行 */
    int total = with_indirect + normal + interrupt;

    printf("取指周期 = %d 节拍\n", fetch);
    printf("间址周期 = %d 节拍\n", indirect);
    printf("执行周期 = %d 节拍\n", execute);
    printf("需间址指令耗时 = %d+%d+%d = %d 节拍\n", fetch, indirect, execute, with_indirect);
    printf("普通指令耗时   = %d+%d = %d 节拍\n", fetch, execute, normal);
    printf("中断周期 = %d 节拍\n", interrupt);
    printf("上述序列总节拍 = %d 节拍\n", total);
    return 0;
}
